17→pub fn run(args: &InitArgs) -> Result<()> {
18→    let storage =
19→        GitStorage::discover().context("Not inside a Git repository. Run `git init` first.")?;
20→
21→    if storage.is_initialized() && !args.force {
22→        println!("Engram is already initialized in this repository.");
23→        println!("Use --force to re-initialize.");
24→        return Ok(());
25→    }
26→
27→    storage
28→        .init_with_remote(args.remote.as_deref())
29→        .context("Failed to initialize engram")?;
30→
31→    // Install git hooks for commit trailer injection
32→    let git_dir = storage.repo().path().to_path_buf();
33→    hooks::install_hooks(&git_dir).context("Failed to install git hooks")?;
34→
35→    println!("Engram initialized. Reasoning capture is ready.");
36→    println!();
37→    println!("Next steps:");
38→    println!("  engram record -- <agent-command>   Record an agent session");
39→    println!("  engram import --auto-detect        Import existing sessions");
40→    println!("  engram log                         List captured engrams");
41→    Ok(())
42→}
