 12→#[derive(Args)]
 13→pub struct PrSummaryArgs {
 14→    /// Commit range (e.g. "main..feature" or "HEAD~5..HEAD")
 15→    pub range: String,
 16→}
 17→
 18→pub fn run(args: &PrSummaryArgs, format: OutputFormat) -> Result<()> {
 19→    let storage = GitStorage::discover().context("Not in a Git repository with engram")?;
 20→
 21→    let parts: Vec<&str> = args.range.splitn(2, "..").collect();
 22→    if parts.len() != 2 {
 23→        anyhow::bail!("Invalid range format. Use 'base..head' (e.g. 'main..feature')");
 24→    }
 25→    let (base, head) = (parts[0], parts[1]);
 26→
 27→    let review = review_branch(&storage, base, head)?;
 28→
 29→    if review.engrams.is_empty() {
 30→        println!("No engrams found in range {}", review.range);
 31→        return Ok(());
 32→    }
 33→
 34→    match format {
 35→        OutputFormat::Json => {
 36→            let json = serde_json::json!({
 37→                "range": review.range,
 38→                "total_commits": review.total_commits,
 39→                "total_tokens": review.total_tokens,
 40→                "total_cost": review.total_cost,
 41→                "engrams": review.engrams.iter().map(|e| {
 42→                    serde_json::json!({
 43→                        "id": e.manifest.id.as_str(),
 44→                        "agent": e.manifest.agent.name,
 45→                        "model": e.manifest.agent.model,
 46→                        "summary": e.manifest.summary,
 47→                        "commit": e.commit_sha,
 48→                        "tokens": e.manifest.token_usage.total_tokens,
 49→                        "cost": e.manifest.token_usage.cost_usd,
 50→                    })
 51→                }).collect::<Vec<_>>(),
 52→                "files_changed": review.files_changed,
 53→            });
 54→            println!("{}", serde_json::to_string_pretty(&json)?);
 55→        }
 56→        OutputFormat::Text => {
 57→            print_text(&storage, &review);
 58→        }
 59→        OutputFormat::Markdown => {
 60→            print_markdown(&storage, &review);
 61→        }
 62→    }
 63→
 64→    Ok(())
 65→}
