 67→fn print_text(storage: &GitStorage, review: &engram_query::review::BranchReview) {
 68→    println!("PR Summary: {}\n", review.range);
 69→
 70→    // Summary from intents
 71→    println!("Summary:");
 72→    for entry in &review.engrams {
 73→        let summary = entry.manifest.summary.as_deref().unwrap_or("(no summary)");
 74→        println!("  - {summary}");
 75→    }
 76→    println!();
 77→
 78→    // Files
 79→    if !review.files_changed.is_empty() {
 80→        println!("Files changed ({}):", review.files_changed.len());
 81→        let mut sorted: Vec<_> = review.files_changed.iter().collect();
 82→        sorted.sort();
 83→        for f in sorted {
 84→            println!("  {f}");
 85→        }
 86→        println!();
 87→    }
 88→
 89→    // Dead ends
 90→    let mut dead_ends = Vec::new();
 91→    for entry in &review.engrams {
 92→        if let Ok(data) = storage.read(entry.manifest.id.as_str()) {
 93→            for de in &data.intent.dead_ends {
 94→                dead_ends.push(format!("{} — {}", de.approach, de.reason));
 95→            }
 96→        }
 97→    }
 98→    if !dead_ends.is_empty() {
 99→        println!("Dead ends:");
100→        for de in &dead_ends {
101→            println!("  - {de}");
102→        }
103→        println!();
104→    }
105→
106→    // Economics
107→    println!("Tokens: {}", review.total_tokens);
108→    if let Some(cost) = review.total_cost {
109→        println!("Cost:   ${cost:.2}");
110→    }
111→    println!("Commits: {}", review.total_commits);
112→}
113→
114→fn print_markdown(storage: &GitStorage, review: &engram_query::review::BranchReview) {
115→    // Summary
116→    println!("## Summary\n");
117→    for entry in &review.engrams {
118→        if let Some(summary) = &entry.manifest.summary {
119→            println!("- {summary}");
120→        }
121→    }
122→    println!();
123→
124→    // Changes — collect file change types from full data
125→    if !review.files_changed.is_empty() {
126→        println!("## Changes\n");
127→        let mut file_types: Vec<(String, String)> = Vec::new();
128→        let mut seen: BTreeSet<String> = BTreeSet::new();
129→
130→        for entry in &review.engrams {
131→            if let Ok(data) = storage.read(entry.manifest.id.as_str()) {
132→                for fc in &data.operations.file_changes {
133→                    if seen.insert(fc.path.clone()) {
134→                        let change_label = match &fc.change_type {
135→                            FileChangeType::Created => "Created",
136→                            FileChangeType::Modified => "Modified",
137→                            FileChangeType::Deleted => "Deleted",
138→                            FileChangeType::Renamed { from } => {
139→                                file_types
140→                                    .push((fc.path.clone(), format!("Renamed from `{from}`")));
141→                                continue;
142→                            }
143→                        };
144→                        file_types.push((fc.path.clone(), change_label.to_string()));
145→                    }
146→                }
147→            }
148→        }
149→
150→        file_types.sort_by(|a, b| a.0.cmp(&b.0));
151→        for (path, change) in &file_types {
152→            println!("- `{path}` — {change}");
153→        }
154→        println!();
155→    }
156→
157→    // Reasoning chain
158→    println!("## Reasoning\n");
159→    for entry in &review.engrams {
160→        let m = &entry.manifest;
161→        let short_id = &entry.commit_sha[..8.min(entry.commit_sha.len())];
162→        let agent = &m.agent.name;
163→        let model = m.agent.model.as_deref().unwrap_or("unknown");
164→        let summary = m.summary.as_deref().unwrap_or("(no summary)");
165→        println!("- **{short_id}** ({agent}/{model}): {summary}");
166→    }
167→    println!();
168→
169→    // Dead ends
170→    let mut dead_ends = Vec::new();
171→    for entry in &review.engrams {
172→        if let Ok(data) = storage.read(entry.manifest.id.as_str()) {
173→            for de in &data.intent.dead_ends {
174→                dead_ends.push(format!("{} — {}", de.approach, de.reason));
175→            }
176→        }
177→    }
178→    if !dead_ends.is_empty() {
179→        println!("## Dead Ends\n");
180→        for de in &dead_ends {
181→            println!("- {de}");
182→        }
183→        println!();
184→    }
185→
186→    // Economics
187→    println!("## Economics\n");
188→    println!("- **Tokens:** {} total", review.total_tokens);
189→    if let Some(cost) = review.total_cost {
190→        println!("- **Cost:** ${cost:.2}");
191→    }
192→    println!("- **Commits:** {}", review.total_commits);
193→    println!();
194→
195→    println!("\u{1f916} Generated with [Engram](https://github.com/AtticAIInc/Engram-SDK)");
196→}
