 11→
 12→#[derive(Args)]
 13→pub struct ImportArgs {
 14→    /// Path to session file or directory
 15→    pub path: Option<PathBuf>,
 16→
 17→    /// Format hint (claude-code or aider)
 18→    #[arg(long = "import-format", value_enum)]
 19→    pub import_format: Option<ImportFormat>,
 20→
 21→    /// Auto-detect and import all discoverable sessions
 22→    #[arg(long)]
 23→    pub auto_detect: bool,
 24→
 25→    /// Only show what would be imported (dry run)
 26→    #[arg(long)]
 27→    pub dry_run: bool,
 28→}
 29→
 30→#[derive(Clone, ValueEnum)]
 31→pub enum ImportFormat {
 32→    ClaudeCode,
 33→    Aider,
 34→}
 35→
 36→/// Check if this engram was already imported (by source hash).
 37→fn check_duplicate(
 38→    storage: &GitStorage,
 39→    data: &engram_core::model::EngramData,
 40→) -> Option<engram_core::model::EngramId> {
 41→    data.manifest
 42→        .source_hash
 43→        .as_deref()
 44→        .and_then(|h| storage.find_by_source_hash(h))
 45→}
 46→
 47→/// Best-effort incremental search index update after storing an engram.
 48→fn try_index(storage: &GitStorage, data: &engram_core::model::EngramData) {
 49→    if let Ok(search) = SearchEngine::open(storage) {
 50→        let _ = search.index_engram(data);
 51→    }
 52→}
 53→
 54→pub fn run(args: &ImportArgs) -> Result<()> {
 55→    let storage = GitStorage::discover().context("Not inside a Git repository")?;
 56→
 57→    if !storage.is_initialized() {
 58→        anyhow::bail!("Engram is not initialized. Run `engram init` first.");
 59→    }
 60→
 61→    if args.auto_detect {
 62→        return run_auto_detect(&storage, args.dry_run);
 63→    }
 64→
 65→    let path = args
 66→        .path
 67→        .as_ref()
 68→        .ok_or_else(|| anyhow::anyhow!("Specify a path or use --auto-detect"))?;
 69→
 70→    let format = args.import_format.as_ref().ok_or_else(|| {
 71→        anyhow::anyhow!("Specify --import-format (claude-code or aider) or use --auto-detect")
 72→    })?;
 73→
 74→    match format {
 75→        ImportFormat::ClaudeCode => {
 76→            println!("Importing Claude Code session: {}", path.display());
 77→            if args.dry_run {
 78→                println!("  (dry run - no changes made)");
 79→                return Ok(());
 80→            }
 81→            let data = ClaudeCodeImporter::import_session(path)
 82→                .context("Failed to parse Claude Code session")?;
 83→            if let Some(existing) = check_duplicate(&storage, &data) {
 84→                println!(
 85→                    "  Skipped (already imported as {})",
 86→                    &existing.as_str()[..8]
 87→                );
 88→                return Ok(());
 89→            }
 90→            let tokens = data.manifest.token_usage.total_tokens;
 91→            let entries = data.transcript.entries.len();
 92→            let id = storage.create(&data).context("Failed to store engram")?;
 93→            try_index(&storage, &data);
 94→            println!(
 95→                "  Imported engram {} ({} transcript entries, {} tokens)",
 96→                &id.as_str()[..8],
 97→                entries,
 98→                tokens
 99→            );
100→        }
101→        ImportFormat::Aider => {
102→            println!("Importing Aider history: {}", path.display());
103→            if args.dry_run {
