 1→use std::collections::BTreeMap;
 2→
 3→use anyhow::{Context, Result};
 4→use engram_core::storage::{GitStorage, ListOptions};
 5→
 6→use crate::output::OutputFormat;
 7→
 8→pub fn run(format: OutputFormat) -> Result<()> {
 9→    let storage = GitStorage::discover().context("Not inside a Git repository")?;
10→
11→    if !storage.is_initialized() {
12→        anyhow::bail!("Engram is not initialized. Run `engram init` first.");
13→    }
14→
15→    let manifests = storage
16→        .list(&ListOptions::default())
17→        .context("Failed to list engrams")?;
18→
19→    if manifests.is_empty() {
20→        println!("No engrams found.");
21→        return Ok(());
22→    }
23→
24→    let total = manifests.len();
25→    let mut total_tokens: u64 = 0;
26→    let mut total_cost: f64 = 0.0;
27→    let mut by_agent: BTreeMap<String, (usize, u64, f64)> = BTreeMap::new();
28→    let mut by_mode: BTreeMap<String, usize> = BTreeMap::new();
29→
30→    let earliest = manifests.last().map(|m| m.created_at);
31→    let latest = manifests.first().map(|m| m.created_at);
32→
33→    for m in &manifests {
34→        total_tokens += m.token_usage.total_tokens;
35→        total_cost += m.token_usage.cost_usd.unwrap_or(0.0);
36→
37→        let entry = by_agent.entry(m.agent.name.clone()).or_default();
38→        entry.0 += 1;
39→        entry.1 += m.token_usage.total_tokens;
40→        entry.2 += m.token_usage.cost_usd.unwrap_or(0.0);
41→
42→        *by_mode.entry(format!("{:?}", m.capture_mode)).or_default() += 1;
43→    }
44→
45→    match format {
46→        OutputFormat::Json => {
47→            let stats = serde_json::json!({
48→                "total_engrams": total,
49→                "total_tokens": total_tokens,
50→                "total_cost_usd": total_cost,
51→                "earliest": earliest,
52→                "latest": latest,
53→                "by_agent": by_agent.iter().map(|(name, (count, tokens, cost))| {
54→                    serde_json::json!({
55→                        "agent": name,
56→                        "count": count,
57→                        "tokens": tokens,
58→                        "cost_usd": cost,
59→                    })
60→                }).collect::<Vec<_>>(),
61→                "by_capture_mode": by_mode,
62→            });
63→            println!("{}", serde_json::to_string_pretty(&stats).unwrap());
64→        }
65→        OutputFormat::Text | OutputFormat::Markdown => {
66→            println!("Engram Statistics");
67→            println!("=================");
68→            println!("Total engrams:  {total}");
69→            println!("Total tokens:   {total_tokens}");
70→            println!("Total cost:     ${total_cost:.2}");
71→            if let (Some(e), Some(l)) = (earliest, latest) {
72→                println!(
73→                    "Date range:     {} to {}",
74→                    e.format("%Y-%m-%d"),
75→                    l.format("%Y-%m-%d")
76→                );
77→            }
78→            println!();
79→
80→            println!("By Agent:");
81→            for (name, (count, tokens, cost)) in &by_agent {
82→                println!("  {name}: {count} engrams, {tokens} tokens, ${cost:.2}");
83→            }
84→            println!();
85→
86→            println!("By Capture Mode:");
87→            for (mode, count) in &by_mode {
88→                println!("  {mode}: {count}");
89→            }
90→        }
91→    }
92→
93→    Ok(())
94→}
