 16→/// MCP server exposing engram reasoning data to AI agents.
 17→///
 18→/// Stores `repo_path: PathBuf` instead of `GitStorage` because
 19→/// `git2::Repository` is `!Send` and rmcp requires `ServerHandler: Send + Sync + 'static`.
 20→/// Each tool handler opens the repository fresh per request.
 21→#[derive(Debug, Clone)]
 22→pub struct EngramMcpServer {
 23→    repo_path: PathBuf,
 24→    tool_router: ToolRouter<Self>,
 25→}
 26→
 27→impl EngramMcpServer {
 28→    /// Create a new MCP server for the repository at the given path.
 29→    pub fn new(repo_path: PathBuf) -> Self {
 30→        Self {
 31→            repo_path,
 32→            tool_router: Self::tool_router(),
 33→        }
 34→    }
 35→
 36→    fn open_storage(&self) -> Result<GitStorage, String> {
 37→        GitStorage::open(&self.repo_path).map_err(|e| format!("Failed to open repository: {e}"))
 38→    }
 39→}
