 90→impl EngramMcpServer {
 91→    #[tool(
 92→        description = "Search engram reasoning history by free-text query. Searches across intent, transcript, file paths, and dead ends."
 93→    )]
 94→    fn engram_search(
 95→        &self,
 96→        Parameters(params): Parameters<SearchParams>,
 97→    ) -> Result<String, String> {
 98→        let storage = self.open_storage()?;
 99→        let engine =
100→            SearchEngine::open(&storage).map_err(|e| format!("Failed to open search: {e}"))?;
101→        let limit = params.limit.unwrap_or(10);
102→        let results = engine
103→            .search(&storage, &params.query, limit)
104→            .map_err(|e| format!("Search failed: {e}"))?;
105→
106→        if results.is_empty() {
107→            return Ok(format!("No results found for: {}", params.query));
108→        }
109→
110→        let mut out = format!(
111→            "Found {} result(s) for: {}\n\n",
112→            results.len(),
113→            params.query
114→        );
115→        for r in &results {
116→            let m = &r.manifest;
117→            let short_id = &m.id.as_str()[..8.min(m.id.as_str().len())];
118→            let summary = m.summary.as_deref().unwrap_or("(no summary)");
119→            let agent = &m.agent.name;
120→            let model = m.agent.model.as_deref().unwrap_or("unknown");
121→            let date = m.created_at.format("%Y-%m-%d %H:%M");
122→            out.push_str(&format!(
123→                "- {short_id} [{agent}/{model}] {date}\n  {summary}\n"
124→            ));
125→        }
126→        Ok(out)
127→    }
128→
129→    #[tool(
130→        description = "Show full details of a specific engram including manifest, intent, file changes, and transcript summary. Supports 'HEAD' for most recent."
131→    )]
132→    fn engram_show(&self, Parameters(params): Parameters<ShowParams>) -> Result<String, String> {
133→        let storage = self.open_storage()?;
134→        let resolved = storage
135→            .resolve(&params.id)
136→            .map_err(|e| format!("Failed to resolve '{}': {e}", params.id))?;
137→        let data = storage
138→            .read(&resolved)
139→            .map_err(|e| format!("Failed to read engram: {e}"))?;
140→
141→        let m = &data.manifest;
142→        let mut out = String::new();
143→        out.push_str(&format!("Engram: {}\n", m.id));
144→        out.push_str(&format!(
145→            "Agent: {}{}\n",
146→            m.agent.name,
147→            m.agent
148→                .model
149→                .as_ref()
150→                .map(|m| format!(" ({m})"))
151→                .unwrap_or_default()
152→        ));
153→        out.push_str(&format!(
154→            "Date: {}\n",
155→            m.created_at.format("%Y-%m-%d %H:%M:%S UTC")
156→        ));
157→        if let Some(summary) = &m.summary {
158→            out.push_str(&format!("Summary: {summary}\n"));
159→        }
160→
161→        let tu = &m.token_usage;
162→        if tu.total_tokens > 0 {
163→            out.push_str(&format!(
164→                "Tokens: {} total ({} in, {} out)",
165→                tu.total_tokens, tu.input_tokens, tu.output_tokens
166→            ));
167→            if let Some(cost) = tu.cost_usd {
168→                out.push_str(&format!("  Cost: ${cost:.4}"));
169→            }
170→            out.push('\n');
171→        }
172→
173→        if !m.git_commits.is_empty() {
174→            out.push_str(&format!("Commits: {}\n", m.git_commits.join(", ")));
175→        }
176→
177→        // Intent
178→        out.push_str(&format!("\nIntent: {}\n", data.intent.original_request));
179→        if let Some(goal) = &data.intent.interpreted_goal {
180→            out.push_str(&format!("Goal: {goal}\n"));
181→        }
182→        if let Some(intent_summary) = &data.intent.summary {
183→            out.push_str(&format!("Intent Summary: {intent_summary}\n"));
184→        }
185→
186→        // File changes
187→        if !data.operations.file_changes.is_empty() {
188→            out.push_str(&format!(
189→                "\nFile Changes ({}):\n",
190→                data.operations.file_changes.len()
191→            ));
192→            for fc in &data.operations.file_changes {
193→                let symbol = match &fc.change_type {
194→                    FileChangeType::Created => "+",
195→                    FileChangeType::Modified => "~",
196→                    FileChangeType::Deleted => "-",
197→                    FileChangeType::Renamed { from } => {
198→                        out.push_str(&format!("  {from} -> {}\n", fc.path));
199→                        continue;
200→                    }
201→                };
202→                out.push_str(&format!("  {symbol} {}\n", fc.path));
203→            }
204→        }
205→
206→        // Dead ends
207→        if !data.intent.dead_ends.is_empty() {
208→            out.push_str("\nDead Ends:\n");
209→            for de in &data.intent.dead_ends {
210→                out.push_str(&format!("  - {}: {}\n", de.approach, de.reason));
211→            }
212→        }
213→
214→        // Decisions
215→        if !data.intent.decisions.is_empty() {
216→            out.push_str("\nDecisions:\n");
217→            for d in &data.intent.decisions {
218→                out.push_str(&format!("  - {}: {}\n", d.description, d.rationale));
219→            }
220→        }
221→
222→        out.push_str(&format!(
223→            "\nTranscript: {} entries\n",
224→            data.transcript.entries.len()
225→        ));
226→
227→        Ok(out)
228→    }
