301→    #[tool(
302→        description = "Compare two engrams showing common files, unique files, and token/cost deltas."
303→    )]
304→    fn engram_diff(&self, Parameters(params): Parameters<DiffParams>) -> Result<String, String> {
305→        let storage = self.open_storage()?;
306→        let data_a = storage
307→            .read(&params.id_a)
308→            .map_err(|e| format!("Failed to find first engram: {e}"))?;
309→        let data_b = storage
310→            .read(&params.id_b)
311→            .map_err(|e| format!("Failed to find second engram: {e}"))?;
312→
313→        let diff: EngramDiff = diff_engrams(&storage, &data_a.manifest.id, &data_b.manifest.id)
314→            .map_err(|e| format!("Diff failed: {e}"))?;
315→
316→        let short_a = &diff.id_a.as_str()[..8.min(diff.id_a.as_str().len())];
317→        let short_b = &diff.id_b.as_str()[..8.min(diff.id_b.as_str().len())];
318→
319→        let mut out = format!("Comparing {short_a} vs {short_b}\n\n");
320→
321→        if !diff.common_files.is_empty() {
322→            out.push_str(&format!("Common files ({}):\n", diff.common_files.len()));
323→            for f in &diff.common_files {
324→                out.push_str(&format!("  {f}\n"));
325→            }
326→        }
327→        if !diff.only_a_files.is_empty() {
328→            out.push_str(&format!(
329→                "Only in {short_a} ({}):\n",
330→                diff.only_a_files.len()
331→            ));
332→            for f in &diff.only_a_files {
333→                out.push_str(&format!("  {f}\n"));
334→            }
335→        }
336→        if !diff.only_b_files.is_empty() {
337→            out.push_str(&format!(
338→                "Only in {short_b} ({}):\n",
339→                diff.only_b_files.len()
340→            ));
341→            for f in &diff.only_b_files {
342→                out.push_str(&format!("  {f}\n"));
343→            }
344→        }
345→
346→        out.push_str(&format!("\nToken delta: {:+}\n", diff.token_delta));
347→        if let Some(cost) = diff.cost_delta {
348→            out.push_str(&format!("Cost delta: {:+.4}\n", cost));
349→        }
350→
351→        Ok(out)
352→    }
