354→    #[tool(
355→        description = "Surface rejected approaches (dead ends) and architectural decisions. Search across all engrams or get dead ends from a specific engram."
356→    )]
357→    fn engram_dead_ends(
358→        &self,
359→        Parameters(params): Parameters<DeadEndsParams>,
360→    ) -> Result<String, String> {
361→        let storage = self.open_storage()?;
362→
363→        if let Some(id) = &params.id {
364→            // Show dead ends from a specific engram
365→            let resolved = storage
366→                .resolve(id)
367→                .map_err(|e| format!("Failed to resolve '{id}': {e}"))?;
368→            let data = storage
369→                .read(&resolved)
370→                .map_err(|e| format!("Failed to read engram: {e}"))?;
371→
372→            let mut out = String::new();
373→            if data.intent.dead_ends.is_empty() && data.intent.decisions.is_empty() {
374→                return Ok(format!(
375→                    "No dead ends or decisions recorded for engram {}",
376→                    &resolved[..8.min(resolved.len())]
377→                ));
378→            }
379→
380→            if !data.intent.dead_ends.is_empty() {
381→                out.push_str("Dead Ends:\n");
382→                for de in &data.intent.dead_ends {
383→                    out.push_str(&format!("  - {}: {}\n", de.approach, de.reason));
384→                }
385→            }
386→            if !data.intent.decisions.is_empty() {
387→                out.push_str("Decisions:\n");
388→                for d in &data.intent.decisions {
389→                    out.push_str(&format!("  - {}: {}\n", d.description, d.rationale));
390→                }
391→            }
392→            return Ok(out);
393→        }
394→
395→        // Search across all engrams for dead ends
396→        let opts = ListOptions {
397→            limit: Some(50),
398→            agent_filter: None,
399→        };
400→        let manifests = storage
401→            .list(&opts)
402→            .map_err(|e| format!("Failed to list engrams: {e}"))?;
403→
404→        let query_lower = params.query.as_deref().unwrap_or("").to_lowercase();
405→        let mut out = String::new();
406→        let mut found = 0;
407→
408→        for m in &manifests {
409→            if let Ok(data) = storage.read(m.id.as_str()) {
410→                let matching_dead_ends: Vec<_> = data
411→                    .intent
412→                    .dead_ends
413→                    .iter()
414→                    .filter(|de| {
415→                        query_lower.is_empty()
416→                            || de.approach.to_lowercase().contains(&query_lower)
417→                            || de.reason.to_lowercase().contains(&query_lower)
418→                    })
419→                    .collect();
420→
421→                let matching_decisions: Vec<_> = data
422→                    .intent
423→                    .decisions
424→                    .iter()
425→                    .filter(|d| {
426→                        query_lower.is_empty()
427→                            || d.description.to_lowercase().contains(&query_lower)
428→                            || d.rationale.to_lowercase().contains(&query_lower)
429→                    })
430→                    .collect();
431→
432→                if !matching_dead_ends.is_empty() || !matching_decisions.is_empty() {
433→                    let short_id = &m.id.as_str()[..8.min(m.id.as_str().len())];
434→                    let summary = m.summary.as_deref().unwrap_or("(no summary)");
435→                    out.push_str(&format!("{short_id} - {summary}:\n"));
436→
437→                    for de in &matching_dead_ends {
438→                        out.push_str(&format!("  Dead end: {} — {}\n", de.approach, de.reason));
439→                        found += 1;
440→                    }
441→                    for d in &matching_decisions {
442→                        out.push_str(&format!(
443→                            "  Decision: {} — {}\n",
444→                            d.description, d.rationale
445→                        ));
446→                        found += 1;
447→                    }
448→                    out.push('\n');
449→                }
450→            }
451→        }
452→
453→        if found == 0 {
454→            if query_lower.is_empty() {
455→                return Ok("No dead ends or decisions found in any engrams.".to_string());
456→            }
457→            return Ok(format!(
458→                "No dead ends or decisions matching '{}' found.",
459→                params.query.as_deref().unwrap_or("")
460→            ));
461→        }
462→
463→        Ok(out)
464→    }
465→}
