493→pub async fn run_stdio(repo_path: PathBuf) -> Result<(), Box<dyn std::error::Error>> {
494→    use rmcp::transport::stdio;
495→    use rmcp::ServiceExt;
496→
497→    let server = EngramMcpServer::new(repo_path);
498→    let service = server.serve(stdio()).await?;
499→    service.waiting().await?;
500→    Ok(())
