  1→use anyhow::{Context, Result};
  2→use clap::Args;
  3→use engram_core::storage::GitStorage;
  4→use engram_query::search::SearchEngine;
  5→
  6→use crate::output::OutputFormat;
  7→
  8→#[derive(Args)]
  9→pub struct BlameArgs {
 10→    /// File path to find reasoning history for
 11→    pub file: String,
 12→
 13→    /// Maximum number of results
 14→    #[arg(short = 'n', long, default_value = "20")]
 15→    pub limit: usize,
 16→}
 17→
 18→pub fn run(args: &BlameArgs, format: OutputFormat) -> Result<()> {
 19→    let storage = GitStorage::discover().context("Not inside a Git repository")?;
 20→
 21→    if !storage.is_initialized() {
 22→        anyhow::bail!("Engram is not initialized. Run `engram init` first.");
 23→    }
 24→
 25→    let search = SearchEngine::open(&storage).context("Failed to open search index")?;
 26→    let results = search
 27→        .search_by_file(&storage, &args.file, args.limit)
 28→        .context("Search failed")?;
 29→
 30→    if results.is_empty() {
 31→        println!("No engrams found that touched '{}'.", args.file);
 32→        return Ok(());
 33→    }
 34→
 35→    match format {
 36→        OutputFormat::Json => {
 37→            let entries: Vec<_> = results
 38→                .iter()
 39→                .map(|r| {
 40→                    // Get actual change type
 41→                    let change_info = storage.read(r.manifest.id.as_str()).ok().and_then(|data| {
 42→                        data.operations
 43→                            .file_changes
 44→                            .iter()
 45→                            .find(|fc| fc.path == args.file)
 46→                            .map(|fc| {
 47→                                serde_json::json!({
 48→                                    "change_type": format!("{:?}", fc.change_type),
 49→                                    "lines_added": fc.lines_added,
 50→                                    "lines_removed": fc.lines_removed,
 51→                                })
 52→                            })
 53→                    });
 54→
 55→                    serde_json::json!({
 56→                        "engram_id": r.manifest.id.as_str(),
 57→                        "created_at": r.manifest.created_at,
 58→                        "agent": r.manifest.agent.name,
 59→                        "summary": r.manifest.summary,
 60→                        "intent": r.manifest.summary,
 61→                        "change": change_info,
 62→                    })
 63→                })
 64→                .collect();
 65→            println!("{}", serde_json::to_string_pretty(&entries).unwrap());
 66→        }
 67→        OutputFormat::Text | OutputFormat::Markdown => {
 68→            println!("Reasoning blame for: {}", args.file);
 69→            println!("{}", "=".repeat(40 + args.file.len()));
 70→            println!();
 71→
 72→            for r in &results {
 73→                let m = &r.manifest;
 74→                let short_id = &m.id.as_str()[..8];
 75→                let date = m.created_at.format("%Y-%m-%d %H:%M");
 76→                let summary = m.summary.as_deref().unwrap_or("(no summary)");
 77→
 78→                // Get change type from full data
 79→                let change_type = storage
 80→                    .read(m.id.as_str())
 81→                    .ok()
 82→                    .and_then(|data| {
 83→                        data.operations
 84→                            .file_changes
 85→                            .iter()
 86→                            .find(|fc| fc.path == args.file)
 87→                            .map(|fc| format!("{:?}", fc.change_type).to_lowercase())
 88→                    })
 89→                    .unwrap_or_else(|| "touched".to_string());
 90→
 91→                println!("{short_id} {date} [{change_type}] {}", m.agent.name);
 92→                println!("  {summary}");
 93→
 94→                // Show intent if we can read it
 95→                if let Ok(data) = storage.read(m.id.as_str()) {
 96→                    let intent = &data.intent.original_request;
 97→                    if intent != summary {
 98→                        println!("  Intent: \"{intent}\"");
 99→                    }
100→                    if !data.intent.dead_ends.is_empty() {
101→                        let dead_ends: Vec<_> =
102→                            data.intent.dead_ends.iter().map(|d| &d.approach).collect();
103→                        println!(
104→                            "  Dead ends: {}",
105→                            dead_ends
106→                                .iter()
107→                                .map(|s| s.as_str())
108→                                .collect::<Vec<_>>()
109→                                .join(", ")
110→                        );
111→                    }
112→                }
113→                println!();
114→            }
115→        }
116→    }
117→
118→    Ok(())
119→}
