372→            let mut out = String::new();
373→            if data.intent.dead_ends.is_empty() && data.intent.decisions.is_empty() {
374→                return Ok(format!(
375→                    "No dead ends or decisions recorded for engram {}",
376→                    &resolved[..8.min(resolved.len())]
377→                ));
378→            }
379→
380→            if !data.intent.dead_ends.is_empty() {
381→                out.push_str("Dead Ends:\n");
382→                for de in &data.intent.dead_ends {
383→                    out.push_str(&format!("  - {}: {}\n", de.approach, de.reason));
384→                }
385→            }
386→            if !data.intent.decisions.is_empty() {
387→                out.push_str("Decisions:\n");
388→                for d in &data.intent.decisions {
389→                    out.push_str(&format!("  - {}: {}\n", d.description, d.rationale));
390→                }
391→            }
392→            return Ok(out);
393→        }
394→
395→        // Search across all engrams for dead ends
396→        let opts = ListOptions {
