410→                let matching_dead_ends: Vec<_> = data
411→                    .intent
412→                    .dead_ends
413→                    .iter()
414→                    .filter(|de| {
415→                        query_lower.is_empty()
416→                            || de.approach.to_lowercase().contains(&query_lower)
417→                            || de.reason.to_lowercase().contains(&query_lower)
418→                    })
419→                    .collect();
420→
421→                let matching_decisions: Vec<_> = data
422→                    .intent
423→                    .decisions
424→                    .iter()
425→                    .filter(|d| {
426→                        query_lower.is_empty()
427→                            || d.description.to_lowercase().contains(&query_lower)
428→                            || d.rationale.to_lowercase().contains(&query_lower)
429→                    })
430→                    .collect();
431→
432→                if !matching_dead_ends.is_empty() || !matching_decisions.is_empty() {
433→                    let short_id = &m.id.as_str()[..8.min(m.id.as_str().len())];
434→                    let summary = m.summary.as_deref().unwrap_or("(no summary)");
435→                    out.push_str(&format!("{short_id} - {summary}:\n"));
436→
437→                    for de in &matching_dead_ends {
438→                        out.push_str(&format!("  Dead end: {} — {}\n", de.approach, de.reason));
439→                        found += 1;
440→                    }
441→                    for d in &matching_decisions {
442→                        out.push_str(&format!(
443→                            "  Decision: {} — {}\n",
444→                            d.description, d.rationale
445→                        ));
446→                        found += 1;
447→                    }
448→                    out.push('\n');
449→                }
450→            }
451→        }
452→
453→        if found == 0 {
454→            if query_lower.is_empty() {
