 8→#[derive(Args)]
 9→pub struct ShowArgs {
10→    /// Engram ID (full or prefix)
11→    pub id: String,
12→
13→    /// Show only the intent
14→    #[arg(long)]
15→    pub intent: bool,
16→
17→    /// Show only the transcript (as JSONL)
18→    #[arg(long)]
19→    pub transcript: bool,
20→
21→    /// Show only operations
22→    #[arg(long)]
23→    pub operations: bool,
24→}
25→
26→pub fn run(args: &ShowArgs, format: OutputFormat) -> Result<()> {
27→    let storage = GitStorage::discover().context("Not inside a Git repository")?;
28→
29→    if !storage.is_initialized() {
30→        anyhow::bail!("Engram is not initialized. Run `engram init` first.");
31→    }
32→
33→    let resolved_id = storage
34→        .resolve(&args.id)
35→        .with_context(|| format!("Failed to resolve engram '{}'", args.id))?;
36→
37→    let data = storage
38→        .read(&resolved_id)
39→        .with_context(|| format!("Failed to read engram '{}'", resolved_id))?;
40→
41→    let output = if args.intent {
42→        format_intent(&data, format)
43→    } else if args.transcript {
44→        match format {
45→            OutputFormat::Json => {
46→                serde_json::to_string_pretty(&data.transcript.entries).unwrap_or_default()
47→            }
48→            OutputFormat::Text | OutputFormat::Markdown => {
49→                let jsonl = data.transcript.to_jsonl().unwrap_or_default();
50→                String::from_utf8_lossy(&jsonl).to_string()
51→            }
52→        }
53→    } else if args.operations {
54→        serde_json::to_string_pretty(&data.operations).unwrap_or_default()
55→    } else {
56→        format_engram_full(&data, format)
57→    };
58→
59→    println!("{output}");
60→    Ok(())
