 1→use anyhow::{Context, Result};
 2→use clap::Args;
 3→
 4→use engram_core::storage::GitStorage;
 5→use engram_query::review_branch;
 6→
 7→use crate::output::OutputFormat;
 8→
 9→#[derive(Args)]
10→pub struct ReviewArgs {
11→    /// Commit range (e.g. "main..feature" or "HEAD~5..HEAD")
12→    pub range: String,
13→}
14→
15→pub fn run(args: &ReviewArgs, format: OutputFormat) -> Result<()> {
16→    let storage = GitStorage::discover().context("Not in a Git repository with engram")?;
17→
18→    // Parse range
19→    let parts: Vec<&str> = args.range.splitn(2, "..").collect();
20→    if parts.len() != 2 {
21→        anyhow::bail!("Invalid range format. Use 'base..head' (e.g. 'main..feature')");
22→    }
23→    let (base, head) = (parts[0], parts[1]);
24→
25→    let review = review_branch(&storage, base, head)?;
26→
27→    match format {
28→        OutputFormat::Json => {
29→            let json = serde_json::json!({
30→                "range": review.range,
31→                "total_commits": review.total_commits,
32→                "engrams": review.engrams.iter().map(|e| {
33→                    serde_json::json!({
34→                        "id": e.manifest.id.as_str(),
35→                        "summary": e.manifest.summary,
36→                        "agent": e.manifest.agent.name,
37→                        "tokens": e.manifest.token_usage.total_tokens,
38→                        "cost": e.manifest.token_usage.cost_usd,
39→                        "commit": e.commit_sha,
40→                    })
41→                }).collect::<Vec<_>>(),
42→                "total_tokens": review.total_tokens,
43→                "total_cost": review.total_cost,
44→                "files_changed": review.files_changed,
45→            });
46→            println!("{}", serde_json::to_string_pretty(&json)?);
47→        }
48→        OutputFormat::Text | OutputFormat::Markdown => {
49→            println!("Branch review: {}\n", review.range);
50→            println!(
51→                "  Commits: {}   Engrams: {}",
52→                review.total_commits,
53→                review.engrams.len()
54→            );
55→            println!("  Total tokens: {}", review.total_tokens);
56→            if let Some(cost) = review.total_cost {
57→                println!("  Total cost: ${cost:.4}");
58→            }
59→            if !review.files_changed.is_empty() {
60→                println!("  Files changed: {}", review.files_changed.len());
61→            }
62→
63→            if !review.engrams.is_empty() {
64→                println!("\nEngrams:");
65→                for entry in &review.engrams {
66→                    let m = &entry.manifest;
67→                    let short_id = &m.id.as_str()[..8];
68→                    let summary = m.summary.as_deref().unwrap_or("(no summary)");
69→                    let commit_short = &entry.commit_sha[..8];
70→                    println!("  {short_id}  [{commit_short}]  {summary}");
71→                }
72→            }
73→        }
74→    }
75→
76→    Ok(())
77→}
