  5→pub fn format_manifest_list(manifests: &[Manifest], show_cost: bool, fmt: OutputFormat) -> String {
  6→    match fmt {
  7→        OutputFormat::Json => serde_json::to_string_pretty(manifests).unwrap_or_default(),
  8→        OutputFormat::Text | OutputFormat::Markdown => {
  9→            format_manifest_list_text(manifests, show_cost)
 10→        }
 11→    }
 12→}
 13→
 14→fn format_manifest_list_text(manifests: &[Manifest], show_cost: bool) -> String {
 15→    if manifests.is_empty() {
 16→        return "No engrams found.".to_string();
 17→    }
 18→
 19→    let mut out = String::new();
 20→    for m in manifests {
 21→        let short_id = &m.id.as_str()[..8.min(m.id.as_str().len())];
 22→        let summary = m.summary.as_deref().unwrap_or("(no summary)");
 23→        let agent = &m.agent.name;
 24→        let model = m.agent.model.as_deref().unwrap_or("");
 25→        let time = m.created_at.format("%Y-%m-%d %H:%M");
 26→
 27→        if show_cost {
 28→            let tokens = m.token_usage.total_tokens;
 29→            let cost = m
 30→                .token_usage
 31→                .cost_usd
 32→                .map(|c| format!("${c:.2}"))
 33→                .unwrap_or_else(|| "-".to_string());
 34→            out.push_str(&format!(
 35→                "\u{25c6} {short_id} {summary} [{agent}/{model}] {cost} {tokens}tok  {time}\n"
 36→            ));
 37→        } else {
 38→            out.push_str(&format!(
 39→                "\u{25c6} {short_id} {summary} [{agent}/{model}]  {time}\n"
 40→            ));
 41→        }
 42→    }
 43→    out
 44→}
 45→
 46→pub fn format_engram_full(data: &EngramData, fmt: OutputFormat) -> String {
 47→    match fmt {
 48→        OutputFormat::Json => serde_json::to_string_pretty(&data.manifest).unwrap_or_default(),
 49→        OutputFormat::Text | OutputFormat::Markdown => format_engram_full_text(data),
 50→    }
 51→}
 52→
 53→fn format_engram_full_text(data: &EngramData) -> String {
 54→    let m = &data.manifest;
 55→    let mut out = String::new();
 56→
 57→    out.push_str(&format!("Engram: {}\n", m.id));
 58→    out.push_str(&format!(
 59→        "Agent:  {}{}\n",
 60→        m.agent.name,
 61→        m.agent
 62→            .model
 63→            .as_ref()
 64→            .map(|m| format!(" ({m})"))
 65→            .unwrap_or_default()
 66→    ));
 67→    out.push_str(&format!(
 68→        "Date:   {}\n",
 69→        m.created_at.format("%Y-%m-%d %H:%M:%S UTC")
 70→    ));
 71→    if let Some(summary) = &m.summary {
 72→        out.push_str(&format!("Summary: {summary}\n"));
 73→    }
 74→
 75→    // Token usage
 76→    let tu = &m.token_usage;
 77→    if tu.total_tokens > 0 {
 78→        out.push_str(&format!(
 79→            "Tokens: {} total ({} in, {} out)",
 80→            tu.total_tokens, tu.input_tokens, tu.output_tokens
 81→        ));
 82→        if let Some(cost) = tu.cost_usd {
 83→            out.push_str(&format!("  Cost: ${cost:.4}"));
 84→        }
 85→        out.push('\n');
 86→    }
 87→
 88→    if !m.git_commits.is_empty() {
 89→        out.push_str(&format!("Commits: {}\n", m.git_commits.join(", ")));
 90→    }
 91→
 92→    if !m.tags.is_empty() {
 93→        out.push_str(&format!("Tags: {}\n", m.tags.join(", ")));
 94→    }
 95→
 96→    // Intent
 97→    out.push_str("\n--- Intent ---\n");
 98→    out.push_str(&data.intent.to_markdown());
 99→
100→    // Operations summary
101→    if !data.operations.file_changes.is_empty() {
102→        out.push_str("\n--- File Changes ---\n");
103→        for fc in &data.operations.file_changes {
104→            let symbol = match &fc.change_type {
105→                engram_core::model::FileChangeType::Created => "+",
106→                engram_core::model::FileChangeType::Modified => "~",
107→                engram_core::model::FileChangeType::Deleted => "-",
108→                engram_core::model::FileChangeType::Renamed { from } => {
109→                    out.push_str(&format!("  {from} -> {}\n", fc.path));
110→                    continue;
111→                }
112→            };
113→            out.push_str(&format!("  {symbol} {}\n", fc.path));
114→        }
115→    }
116→
117→    if !data.operations.tool_calls.is_empty() {
118→        out.push_str(&format!(
119→            "\n--- Tool Calls ({}) ---\n",
120→            data.operations.tool_calls.len()
121→        ));
122→        for tc in &data.operations.tool_calls {
123→            let err_marker = if tc.is_error { " [ERROR]" } else { "" };
124→            out.push_str(&format!("  {}{err_marker}\n", tc.tool_name));
125→        }
126→    }
127→
128→    // Transcript summary
129→    out.push_str(&format!(
130→        "\n--- Transcript ({} entries) ---\n",
131→        data.transcript.entries.len()
132→    ));
133→
134→    out
135→}
136→
137→pub fn format_intent(data: &EngramData, fmt: OutputFormat) -> String {
138→    match fmt {
139→        OutputFormat::Json => serde_json::to_string_pretty(&data.intent).unwrap_or_default(),
140→        OutputFormat::Text | OutputFormat::Markdown => data.intent.to_markdown(),
141→    }
142→}
