  6→/// A single engram found during a branch review.
  7→#[derive(Debug, Clone)]
  8→pub struct ReviewEntry {
  9→    pub manifest: Manifest,
 10→    pub commit_sha: String,
 11→}
 12→
 13→/// Result of reviewing a branch range.
 14→#[derive(Debug)]
 15→pub struct BranchReview {
 16→    pub range: String,
 17→    pub engrams: Vec<ReviewEntry>,
 18→    pub total_commits: usize,
 19→    pub total_tokens: u64,
 20→    pub total_cost: Option<f64>,
 21→    pub files_changed: Vec<String>,
 22→}
 23→
 24→/// Review a branch by walking git log for `base..head`, finding commits
 25→/// with `Engram-Id` trailers, and collecting referenced engrams.
 26→pub fn review_branch(
 27→    storage: &GitStorage,
 28→    base: &str,
 29→    head: &str,
 30→) -> Result<BranchReview, QueryError> {
 31→    let repo = storage.repo();
 32→    let range = format!("{base}..{head}");
 33→
 34→    // Resolve base and head
 35→    let head_obj = repo
 36→        .revparse_single(head)
 37→        .map_err(|e| QueryError::Search(format!("Cannot resolve '{head}': {e}")))?;
 38→    let base_obj = repo
 39→        .revparse_single(base)
 40→        .map_err(|e| QueryError::Search(format!("Cannot resolve '{base}': {e}")))?;
 41→
 42→    // Walk from head to base
 43→    let mut revwalk = repo
 44→        .revwalk()
 45→        .map_err(|e| QueryError::Search(format!("Cannot create revwalk: {e}")))?;
 46→    revwalk
 47→        .push(head_obj.id())
 48→        .map_err(|e| QueryError::Search(format!("Cannot push head: {e}")))?;
 49→    revwalk
 50→        .hide(base_obj.id())
 51→        .map_err(|e| QueryError::Search(format!("Cannot hide base: {e}")))?;
 52→
 53→    let mut engrams = Vec::new();
 54→    let mut total_commits = 0;
 55→    let mut seen_engram_ids = std::collections::HashSet::new();
 56→    let mut all_files = std::collections::HashSet::new();
 57→
 58→    for oid_result in revwalk {
 59→        let oid = oid_result.map_err(|e| QueryError::Search(format!("Revwalk error: {e}")))?;
 60→        let commit = repo
 61→            .find_commit(oid)
 62→            .map_err(|e| QueryError::Search(format!("Cannot find commit {oid}: {e}")))?;
 63→
 64→        total_commits += 1;
 65→        let sha = oid.to_string();
 66→
 67→        // Check commit message for Engram-Id trailer
 68→        if let Some(message) = commit.message() {
 69→            for line in message.lines() {
 70→                if let Some(engram_id) = line.strip_prefix("Engram-Id: ") {
 71→                    let engram_id = engram_id.trim();
 72→                    if seen_engram_ids.insert(engram_id.to_string()) {
 73→                        // Try to read the engram
 74→                        if let Ok(data) = storage.read(engram_id) {
 75→                            // Collect files
 76→                            for fc in &data.operations.file_changes {
 77→                                all_files.insert(fc.path.clone());
 78→                            }
 79→                            engrams.push(ReviewEntry {
 80→                                manifest: data.manifest,
 81→                                commit_sha: sha.clone(),
 82→                            });
 83→                        }
 84→                    }
 85→                }
 86→            }
 87→        }
 88→    }
 89→
 90→    // Compute totals
 91→    let total_tokens: u64 = engrams
 92→        .iter()
 93→        .map(|e| e.manifest.token_usage.total_tokens)
 94→        .sum();
 95→
 96→    let total_cost: Option<f64> = {
 97→        let costs: Vec<f64> = engrams
 98→            .iter()
 99→            .filter_map(|e| e.manifest.token_usage.cost_usd)
100→            .collect();
101→        if costs.is_empty() {
102→            None
103→        } else {
104→            Some(costs.iter().sum())
105→        }
106→    };
107→
108→    Ok(BranchReview {
109→        range,
110→        engrams,
111→        total_commits,
112→        total_tokens,
113→        total_cost,
114→        files_changed: all_files.into_iter().collect(),
115→    })
116→}
