252→        let repo = Repository::init(tmp.path()).unwrap();
253→        {
254→            let mut config = repo.config().unwrap();
255→            config.set_str("user.name", "Test").unwrap();
256→            config.set_str("user.email", "test@example.com").unwrap();
257→        }
258→
259→        let storage = GitStorage::open(tmp.path()).unwrap();
260→        storage.init().unwrap();
261→
262→        let data = make_test_data("Add auth", &["src/auth.rs"], 1000, None);
263→        let id = storage.create(&data).unwrap();
264→
265→        let base = make_commit(&repo, "base commit", None);
266→        let msg1 = format!("commit 1\n\nEngram-Id: {}", id.as_str());
267→        let mid = make_commit(&repo, &msg1, Some(base));
268→        let msg2 = format!("commit 2\n\nEngram-Id: {}", id.as_str());
269→        let head = make_commit(&repo, &msg2, Some(mid));
270→
271→        let review = review_branch(&storage, &base.to_string(), &head.to_string()).unwrap();
272→
273→        // Same engram ID should only appear once
274→        assert_eq!(review.engrams.len(), 1);
275→        assert_eq!(review.total_commits, 2);
276→    }
277→}
