113→   113→    #[tool(
114→   114→        description = "Search engram reasoning history by free-text query. Searches across intent, transcript, file paths, and dead ends."
115→   115→    )]
116→   116→    fn engram_search(
117→   117→        &self,
118→   118→        Parameters(params): Parameters<SearchParams>,
119→   119→    ) -> Result<String, String> {
120→   120→        let storage = self.open_storage()?;
121→   121→        let engine =
122→   122→            SearchEngine::open(&storage).map_err(|e| format!("Failed to open search: {e}"))?;
123→   123→        let limit = params.limit.unwrap_or(10);
124→   124→        let results = engine
125→   125→            .search(&storage, &params.query, limit)
126→   126→            .map_err(|e| format!("Search failed: {e}"))?;
127→   127→
128→   128→        if results.is_empty() {
129→   129→            return Ok(format!("No results found for: {}", params.query));
130→   130→        }
131→   131→
132→   132→        let mut out = format!(
133→   133→            "Found {} result(s) for: {}\n\n",
134→   134→            results.len(),
135→   135→            params.query
136→   136→        );
137→   137→        for r in &results {
138→   138→            let m = &r.manifest;
139→   139→            let short_id = &m.id.as_str()[..8.min(m.id.as_str().len())];
140→   140→            let summary = m.summary.as_deref().unwrap_or("(no summary)");
141→   141→            let agent = &m.agent.name;
142→   142→            let model = m.agent.model.as_deref().unwrap_or("unknown");
143→   143→            let date = m.created_at.format("%Y-%m-%d %H:%M");
144→   144→            out.push_str(&format!(
145→   145→                "- {short_id} [{agent}/{model}] {date}\n  {summary}\n"
146→   146→            ));
147→   147→        }
148→   148→        Ok(out)
149→   149→    }
