151→   151→    #[tool(
152→   152→        description = "Show full details of a specific engram including manifest, intent, file changes, and transcript summary. Supports 'HEAD' for most recent."
153→   153→    )]
154→   154→    fn engram_show(&self, Parameters(params): Parameters<ShowParams>) -> Result<String, String> {
155→   155→        let storage = self.open_storage()?;
156→   156→        let resolved = storage
157→   157→            .resolve(&params.id)
158→   158→            .map_err(|e| format!("Failed to resolve '{}': {e}", params.id))?;
159→   159→        let data = storage
160→   160→            .read(&resolved)
161→   161→            .map_err(|e| format!("Failed to read engram: {e}"))?;
162→   162→
163→   163→        let m = &data.manifest;
164→   164→        let mut out = String::new();
165→   165→        out.push_str(&format!("Engram: {}\n", m.id));
166→   166→        out.push_str(&format!(
167→   167→            "Agent: {}{}\n",
168→   168→            m.agent.name,
169→   169→            m.agent
170→   170→                .model
171→   171→                .as_ref()
172→   172→                .map(|m| format!(" ({m})"))
173→   173→                .unwrap_or_default()
174→   174→        ));
175→   175→        out.push_str(&format!(
176→   176→            "Date: {}\n",
177→   177→            m.created_at.format("%Y-%m-%d %H:%M:%S UTC")
178→   178→        ));
179→   179→        if let Some(summary) = &m.summary {
180→   180→            out.push_str(&format!("Summary: {summary}\n"));
181→   181→        }
182→   182→
183→   183→        let tu = &m.token_usage;
184→   184→        if tu.total_tokens > 0 {
185→   185→            out.push_str(&format!(
186→   186→                "Tokens: {} total ({} in, {} out)",
187→   187→                tu.total_tokens, tu.input_tokens, tu.output_tokens
188→   188→            ));
189→   189→            if let Some(cost) = tu.cost_usd {
190→   190→                out.push_str(&format!("  Cost: ${cost:.4}"));
191→   191→            }
192→   192→            out.push('\n');
193→   193→        }
194→   194→
195→   195→        if !m.git_commits.is_empty() {
196→   196→            out.push_str(&format!("Commits: {}\n", m.git_commits.join(", ")));
197→   197→        }
198→   198→
199→   199→        // Intent
200→   200→        out.push_str(&format!("\nIntent: {}\n", data.intent.original_request));

200→   200→        out.push_str(&format!("\nIntent: {}\n", data.intent.original_request));
201→   201→        if let Some(goal) = &data.intent.interpreted_goal {
202→   202→            out.push_str(&format!("Goal: {goal}\n"));
203→   203→        }
204→   204→        if let Some(intent_summary) = &data.intent.summary {
205→   205→            out.push_str(&format!("Intent Summary: {intent_summary}\n"));
206→   206→        }
207→   207→
208→   208→        // File changes
209→   209→        if !data.operations.file_changes.is_empty() {
210→   210→            out.push_str(&format!(
211→   211→                "\nFile Changes ({}):\n",
212→   212→                data.operations.file_changes.len()
213→   213→            ));
214→   214→            for fc in &data.operations.file_changes {
215→   215→                let symbol = match &fc.change_type {
216→   216→                    FileChangeType::Created => "+",
217→   217→                    FileChangeType::Modified => "~",
218→   218→                    FileChangeType::Deleted => "-",
219→   219→                    FileChangeType::Renamed { from } => {
220→   220→                        out.push_str(&format!("  {from} -> {}\n", fc.path));
221→   221→                        continue;
222→   222→                    }
223→   223→                };
224→   224→                out.push_str(&format!("  {symbol} {}\n", fc.path));
225→   225→            }
226→   226→        }
227→   227→
228→   228→        // Dead ends
229→   229→        if !data.intent.dead_ends.is_empty() {
230→   230→            out.push_str("\nDead Ends:\n");
231→   231→            for de in &data.intent.dead_ends {
232→   232→                out.push_str(&format!("  - {}: {}\n", de.approach, de.reason));
233→   233→            }
234→   234→        }
235→   235→
236→   236→        // Decisions
237→   237→        if !data.intent.decisions.is_empty() {
238→   238→            out.push_str("\nDecisions:\n");
239→   239→            for d in &data.intent.decisions {
240→   240→                out.push_str(&format!("  - {}: {}\n", d.description, d.rationale));
241→   241→            }
242→   242→        }
243→   243→
244→   244→        out.push_str(&format!(
245→   245→            "\nTranscript: {} entries\n",
246→   246→            data.transcript.entries.len()
247→   247→        ));
248→   248→
249→   249→        Ok(out)
250→   250→    }
