340→   340→
341→   341→        let mut out = format!("Comparing {short_a} vs {short_b}\n\n");
342→   342→
343→   343→        if !diff.common_files.is_empty() {
344→   344→            out.push_str(&format!("Common files ({}):\n", diff.common_files.len()));
345→   345→            for f in &diff.common_files {
346→   346→                out.push_str(&format!("  {f}\n"));
347→   347→            }
348→   348→        }
349→   349→        if !diff.only_a_files.is_empty() {
350→   350→            out.push_str(&format!(
351→   351→                "Only in {short_a} ({}):\n",
352→   352→                diff.only_a_files.len()
353→   353→            ));
354→   354→            for f in &diff.only_a_files {
355→   355→                out.push_str(&format!("  {f}\n"));
356→   356→            }
357→   357→        }
358→   358→        if !diff.only_b_files.is_empty() {
359→   359→            out.push_str(&format!(
360→   360→                "Only in {short_b} ({}):\n",
361→   361→                diff.only_b_files.len()
362→   362→            ));
363→   363→            for f in &diff.only_b_files {
364→   364→                out.push_str(&format!("  {f}\n"));
365→   365→            }
366→   366→        }
367→   367→
368→   368→        out.push_str(&format!("\nToken delta: {:+}\n", diff.token_delta));
369→   369→        if let Some(cost) = diff.cost_delta {
370→   370→            out.push_str(&format!("Cost delta: {:+.4}\n", cost));
371→   371→        }
372→   372→
373→   373→        Ok(out)
374→   374→    }
