376→   376→    #[tool(
377→   377→        description = "Surface rejected approaches (dead ends) and architectural decisions. Search across all engrams or get dead ends from a specific engram. Use recurring=true to find approaches tried and rejected multiple times."
378→   378→    )]
379→   379→    fn engram_dead_ends(
380→   380→        &self,
381→   381→        Parameters(params): Parameters<DeadEndsParams>,
382→   382→    ) -> Result<String, String> {
383→   383→        let storage = self.open_storage()?;
384→   384→
385→   385→        if let Some(id) = &params.id {
386→   386→            // Show dead ends from a specific engram
387→   387→            let resolved = storage
388→   388→                .resolve(id)
389→   389→                .map_err(|e| format!("Failed to resolve '{id}': {e}"))?;
390→   390→            let data = storage
391→   391→                .read(&resolved)
392→   392→                .map_err(|e| format!("Failed to read engram: {e}"))?;
393→   393→
394→   394→            let mut out = String::new();
395→   395→            if data.intent.dead_ends.is_empty() && data.intent.decisions.is_empty() {
396→   396→                return Ok(format!(
397→   397→                    "No dead ends or decisions recorded for engram {}",
398→   398→                    &resolved[..8.min(resolved.len())]
399→   399→                ));

400→   400→            }
401→   401→
402→   402→            if !data.intent.dead_ends.is_empty() {
403→   403→                out.push_str("Dead Ends:\n");
404→   404→                for de in &data.intent.dead_ends {
405→   405→                    out.push_str(&format!("  - {}: {}\n", de.approach, de.reason));
406→   406→                }
407→   407→            }
408→   408→            if !data.intent.decisions.is_empty() {
409→   409→                out.push_str("Decisions:\n");
410→   410→                for d in &data.intent.decisions {
411→   411→                    out.push_str(&format!("  - {}: {}\n", d.description, d.rationale));
412→   412→                }
413→   413→            }
414→   414→            return Ok(out);
415→   415→        }
416→   416→
417→   417→        // Search across all engrams for dead ends
418→   418→        let opts = ListOptions {
419→   419→            limit: Some(50),
420→   420→            agent_filter: None,
421→   421→        };
422→   422→        let manifests = storage
423→   423→            .list(&opts)
424→   424→            .map_err(|e| format!("Failed to list engrams: {e}"))?;
425→   425→
426→   426→        let query_lower = params.query.as_deref().unwrap_or("").to_lowercase();
427→   427→
428→   428→        // Recurring mode: group by normalized approach name
429→   429→        if params.recurring.unwrap_or(false) {
430→   430→            let mut groups: std::collections::BTreeMap<String, Vec<(String, String, String)>> =
431→   431→                std::collections::BTreeMap::new();
432→   432→
433→   433→            for m in &manifests {
434→   434→                if let Ok(data) = storage.read(m.id.as_str()) {
435→   435→                    for de in &data.intent.dead_ends {
436→   436→                        if !query_lower.is_empty()
437→   437→                            && !de.approach.to_lowercase().contains(&query_lower)
438→   438→                            && !de.reason.to_lowercase().contains(&query_lower)
439→   439→                        {
440→   440→                            continue;
441→   441→                        }
442→   442→                        let normalized = de.approach.trim().to_lowercase();
443→   443→                        let short_id = m.id.as_str()[..8.min(m.id.as_str().len())].to_string();
444→   444→                        let date = m.created_at.format("%Y-%m-%d").to_string();
445→   445→                        groups.entry(normalized).or_default().push((
446→   446→                            short_id,
447→   447→                            date,
448→   448→                            de.reason.clone(),
449→   449→                        ));
450→   450→                    }
451→   451→                }
452→   452→            }
453→   453→
454→   454→            let mut recurring: Vec<_> = groups.into_iter().filter(|(_, v)| v.len() >= 2).collect();
455→   455→            recurring.sort_by(|a, b| b.1.len().cmp(&a.1.len()));
456→   456→
457→   457→            if recurring.is_empty() {
458→   458→                return Ok("No recurring dead ends found.".to_string());
459→   459→            }
460→   460→
461→   461→            let mut out = String::from("Recurring Dead Ends:\n\n");
