    #[test]
    fn test_lookup_opus() {
        let p = lookup_model("claude-opus-4-6").unwrap();
        assert!((p.input_per_million - 15.0).abs() < 1e-10);
        assert!((p.output_per_million - 75.0).abs() < 1e-10);
    }

